-- Reproducible initial ASLAN Academy catalogue and draft learning content.
-- All content stays in draft until the academy owner reviews pricing, media, assessments and publication.
insert into public.academy_schools(slug,name,description,default_language,supported_languages,status)
select 'aslan-academy','أكاديمية ASLAN','أكاديمية ASLAN للتكوين المهني والتقني.','ar',array['ar','fr','en']::text[],'active'
where not exists(select 1 from public.academy_schools where slug='aslan-academy');

insert into public.academy_branches(school_id,slug,name,address,timezone,language,status)
select s.id,'batna','فرع باتنة','','Africa/Algiers','ar','active'
from public.academy_schools s
where s.slug='aslan-academy'
and not exists(select 1 from public.academy_branches b where b.school_id=s.id and b.slug='batna');

insert into public.courses(title,description,duration,price_dzd,status)
select v.title,v.description,v.duration,null,'draft'
from (values
('مبادئ التنجيد وصناعة الكراسي','مسار تأسيسي تطبيقي لفهم هيكل الكرسي، اختيار الإسفنج والأقمشة، القص والخياطة، التنجيد والتجميع وضبط الجودة والتكلفة.','مسار تأسيسي — 4 أسابيع، يحدد الجدول النهائي قبل النشر'),
('الخياطة الصناعية وتصميم المفروشات والستائر','تكوين عملي في تجهيز آلة الخياطة، قراءة القياسات، القص وتقليل الهدر، تنفيذ أغطية الوسائد والمفروشات والستائر وتشطيب المنتج وفحصه.','مسار تأسيسي — 4 أسابيع، يحدد الجدول النهائي قبل النشر'),
('الكهرباء المعمارية والصناعية','تكوين في السلامة الكهربائية، قراءة المخططات، اختيار المقاطع والحمايات، تمديدات المباني ومبادئ دوائر التحكم الصناعي والاختبار الآمن.','مسار تأسيسي — 6 أسابيع، يحدد الجدول النهائي قبل النشر'),
('التبريد والتكييف والتدفئة','تكوين في مبادئ دورة التبريد، مكونات أجهزة التكييف، التشخيص المنهجي، الصيانة الوقائية، أساسيات التدفئة المركزية والسلامة.','مسار تأسيسي — 6 أسابيع، يحدد الجدول النهائي قبل النشر'),
('النجارة وصناعة الأثاث باستخدام MDF','تكوين في القياس والرسم التنفيذي، تخطيط ألواح MDF، القص والحواف والتجميع واختيار المثبتات والتشطيب وفحص استقامة الأثاث.','مسار تأسيسي — 5 أسابيع، يحدد الجدول النهائي قبل النشر'),
('اللحام والأعمال المعدنية','تكوين تمهيدي في السلامة، قراءة الأبعاد، تجهيز القطع، مبادئ وصل المعادن، فحص الوصلات وترتيب العمل في الورشة.','مسار تأسيسي — 4 أسابيع، يحدد الجدول النهائي قبل النشر')
) as v(title,description,duration)
where not exists(select 1 from public.courses c where c.title=v.title);

insert into public.academy_modules(course_id,title,description,sort_order,status)
select c.id::text,v.title,v.description,v.sort_order,'draft'
from (values
('مبادئ التنجيد وصناعة الكراسي','الخامات والقياس والسلامة','الأدوات والخامات وقياس الأجزاء وتوثيق المقاسات قبل التصنيع.',1),
('مبادئ التنجيد وصناعة الكراسي','الإسفنج والقماش والقص','حساب الخامات واختيار الكثافات والقماش وتنظيم القص لتقليل الهدر.',2),
('مبادئ التنجيد وصناعة الكراسي','التجميع والتشطيب والجودة','التنجيد وفحص الثبات والتناظر والتشطيب وحساب تكلفة الوحدة.',3),
('الخياطة الصناعية وتصميم المفروشات والستائر','الآلة والخيط والغرز','ضبط الآلة والإبرة والخيط واختبار الغرزة والسلامة.',1),
('الخياطة الصناعية وتصميم المفروشات والستائر','القياس والبترون والقص','تحويل القياسات إلى بترون ومراعاة بدل الخياطة واتجاه النسيج.',2),
('الخياطة الصناعية وتصميم المفروشات والستائر','التجميع والتشطيب والفحص','تنفيذ الخياطة وفحص الاستقامة والمتانة ونظافة المنتج.',3),
('الكهرباء المعمارية والصناعية','السلامة والقياس الكهربائي','العزل والتحقق من انعدام الجهد واستخدام أجهزة القياس بأمان.',1),
('الكهرباء المعمارية والصناعية','المخططات والتمديدات والحماية','قراءة الرموز وتحديد الدوائر والمقاطع والحمايات وفق التصميم.',2),
('الكهرباء المعمارية والصناعية','دوائر التحكم والاختبار','مقدمة في التحكم الصناعي والاختبارات والتوثيق قبل إعادة التغذية.',3),
('التبريد والتكييف والتدفئة','المكونات ودورة التبريد','الضاغط والمكثف وصمام التمدد والمبخر وانتقال الحرارة.',1),
('التبريد والتكييف والتدفئة','التشخيص والصيانة الوقائية','جمع الأعراض والقياسات وفحص الفلاتر وتدفق الهواء والتوصيلات.',2),
('التبريد والتكييف والتدفئة','التدفئة والسلامة والتسليم','مبادئ التدفئة المركزية وفحوص السلامة وتقرير التدخل.',3),
('النجارة وصناعة الأثاث باستخدام MDF','القياس والرسم التنفيذي','إعداد قائمة القطع والأبعاد وسماحات التجميع قبل القص.',1),
('النجارة وصناعة الأثاث باستخدام MDF','القص والحواف والتجميع','ترتيب القص وترقيم القطع ومعالجة الحواف واختيار المثبتات.',2),
('النجارة وصناعة الأثاث باستخدام MDF','التركيب والتشطيب والجودة','ضبط الزوايا والاستقامة والأبواب والأدراج وفحص التشطيب.',3),
('اللحام والأعمال المعدنية','السلامة وتجهيز القطع','معدات الوقاية وتثبيت القطع وتنظيف الأسطح وقراءة المقاسات.',1),
('اللحام والأعمال المعدنية','مبادئ الوصل والتحكم','اختيار أسلوب الوصل وفق المادة والسماكة وتجربة عينة.',2),
('اللحام والأعمال المعدنية','الفحص والتشطيب وتنظيم الورشة','فحص الوصلات وإزالة الحواف الحادة وتنظيم الورشة وتوثيق النتائج.',3)
) as v(course_title,title,description,sort_order)
join public.courses c on c.title=v.course_title
where not exists(select 1 from public.academy_modules m where m.course_id=c.id::text and m.title=v.title);

insert into public.academy_lessons(module_id,title,lesson_type,body,duration_minutes,sort_order,status)
select m.id,v.lesson_title,'text',v.body,25,v.sort_order,'draft'
from (values
('مبادئ التنجيد وصناعة الكراسي','الخامات والقياس والسلامة','قائمة فحص محطة التنجيد','قبل البدء، افحص ثبات طاولة العمل وسلامة أدوات القص والتثبيت، وافصل أي أداة كهربائية قبل ضبطها. سجّل عرض المقعد وعمقه وارتفاعه ومقاسات الظهر، ثم ميّز بين أبعاد الهيكل وأبعاد الإسفنج بعد ضغطه. أنشئ ورقة خامات تشمل الخشب أو MDF، الإسفنج، القماش، الخيوط، الدبابيس ومواد التثبيت. لا تعتمد القياس التقريبي عندما يؤثر اختلاف السنتيمترات في شد القماش أو تماثل القطعتين.',1),
('مبادئ التنجيد وصناعة الكراسي','الإسفنج والقماش والقص','حساب الخامات قبل القص','اختر كثافة الإسفنج بحسب وظيفة الجزء وطريقة الاستخدام، ولا تخلط بين الكثافة والصلابة. افرد القماش وحدد اتجاه الوبرة أو النقشة قبل وضع البترون، ثم أضف بدل الخياطة والالتفاف والتثبيت وفق تصميم القطعة. رتّب القطع الكبيرة أولًا، واحتفظ ببطاقة لكل قطعة تتضمن اسمها واتجاهها وعددها. قارن الاستهلاك الفعلي بالمخطط بعد القص لتحديد الهدر وتصحيح تقدير تكلفة الدفعة التالية.',2),
('مبادئ التنجيد وصناعة الكراسي','التجميع والتشطيب والجودة','فحص المنتج النهائي','افحص استقامة الهيكل وثبات الوصلات قبل تغطيته، ثم تأكد من توزيع الإسفنج دون فراغات أو تكتلات. أثناء شد القماش، وزّع الشد تدريجيًا من المنتصف إلى الأطراف وتحقق من تماثل الزوايا وعدم ظهور تجاعيد. في الفحص النهائي، راجع ثبات الكرسي، تساوي الارتفاعات، نظافة الخياطة، إخفاء المثبتات، وسلامة الحواف. سجّل زمن العمل والمواد المستهلكة والعيوب لإسناد سعر بيع مبني على التكلفة الفعلية.',3),
('الخياطة الصناعية وتصميم المفروشات والستائر','الآلة والخيط والغرز','اختبار الغرزة قبل الإنتاج','اختيار الإبرة والخيط وشد الخيط مرتبط بنوع القماش وسماكته. ابدأ بعينة من بقايا القماش نفسه، واضبط طول الغرزة والشد حتى تكون الغرزة متوازنة على الوجه والظهر. افحص انقطاع الخيط وتجمع القماش وتخطي الغرز، ولا تبدأ دفعة كاملة قبل نجاح العينة. التزم بحماية الأصابع وفصل الطاقة عند تغيير الإبرة أو إزالة التشابك.',1),
('الخياطة الصناعية وتصميم المفروشات والستائر','القياس والبترون والقص','بناء مخطط قص اقتصادي','حوّل قياسات المنتج النهائي إلى أبعاد قص مع إضافة بدل الخياطة والثنيات والجيوب المطلوبة. تحقق من اتجاه النقشة والوبر قبل وضع البترون، واجمع القطع المتشابهة في مخطط واحد لتقليل الهدر. علّم كل قطعة برمز يوضح المنتج والجهة والعدد، وراجع القياسات مرتين قبل القص لأن الخطأ في القص غالبًا لا يمكن إصلاحه دون استهلاك إضافي.',2),
('الخياطة الصناعية وتصميم المفروشات والستائر','التجميع والتشطيب والفحص','معايير قبول المفروشات','رتّب خطوات الخياطة بحيث تُنفّذ العمليات المتشابهة على دفعات، مع فحص بعد كل مرحلة حرجة. تحقق من استقامة الدرزات وتساوي الحواف وثبات الأطراف ومطابقة الأبعاد النهائية للمقاس المطلوب. في الستائر، راجع توزيع الثنيات أو الحلقات وتساوي الطول عند التعليق. سجّل أي عيب ونقطة حدوثه لتقليل تكراره بدل الاكتفاء بإصلاح القطعة النهائية.',3),
('الكهرباء المعمارية والصناعية','السلامة والقياس الكهربائي','قاعدة التحقق قبل العمل','لا يبدأ العمل الكهربائي إلا بواسطة شخص مؤهل وبإجراء عزل مناسب للمصدر، وتأمين ضد إعادة التشغيل، والتحقق من جهاز القياس قبل وبعد اختبار انعدام الجهد. لا تعتمد على مفتاح مغلق أو مؤشر ضوئي وحده لإثبات انعدام الجهد. استخدم معدات الوقاية والأدوات المصنفة للمهمة، وأوقف العمل عند غموض المخطط أو وجود تلف أو ظروف غير آمنة.',1),
('الكهرباء المعمارية والصناعية','المخططات والتمديدات والحماية','من المخطط إلى قائمة الدوائر','ابدأ بمراجعة الرموز ومصدر التغذية والأحمال المتوقعة وظروف التركيب. أنشئ جدولًا لكل دائرة يضم الغرض والحمل وطول المسار والمقطع والحماية وطريقة الفصل، ثم تحقق من توافق الاختيارات مع اللوائح المحلية والمواصفات المعتمدة. هذه المراجعة تعليمية ولا تحل محل التصميم المعتمد أو فحص كهربائي مؤهل قبل التشغيل.',2),
('الكهرباء المعمارية والصناعية','دوائر التحكم والاختبار','اختبار ما قبل التسليم','افصل القدرة قبل فحص التوصيلات، وقارن كل نقطة بالمخطط، ثم نفّذ اختبارات الاستمرارية والعزل والقطبية والتأريض باستخدام إجراءات ومعدات مناسبة. في دوائر التحكم، تحقق من منطق التشغيل والإيقاف والحماية قبل تجربة الحمل. وثّق النتائج وأي اختلاف، ولا تعِد التغذية إذا بقي خلل أو لم تكتمل اختبارات السلامة.',3),
('التبريد والتكييف والتدفئة','المكونات ودورة التبريد','تتبع انتقال الحرارة','تعرّف على وظيفة الضاغط والمكثف وجهاز التمدد والمبخر، وتتبع انتقال الحرارة وتغير حالة وسيط التبريد في كل جزء. اربط الملاحظة بقياس موثوق بدل استبدال القطع بالتخمين. يجب التعامل مع وسيط التبريد والضغط والكهرباء وفق التدريب والأنظمة المعمول بها، ولا تُفتح الدائرة أو تُشحن دون تجهيز وترخيص مناسبين.',1),
('التبريد والتكييف والتدفئة','التشخيص والصيانة الوقائية','تشخيص منظم قبل استبدال القطع','ابدأ بتسجيل شكوى المستخدم وظروف التشغيل، ثم افحص الفلاتر وتدفق الهواء ونظافة المبادلات والتوصيلات الظاهرة. قارن القياسات ببيانات المصنع وظروف التشغيل، وغيّر متغيرًا واحدًا في كل مرة عندما يكون ذلك آمنًا. افصل التغذية قبل أعمال الصيانة، ولا تتعامل مع الضغط أو وسيط التبريد دون معدات وإجراءات مناسبة.',2),
('التبريد والتكييف والتدفئة','التدفئة والسلامة والتسليم','قائمة فحص التسليم','تحقق من عدم وجود تسرب ظاهر أو توصيلات غير محمية، ومن ثبات الوحدة وتصريف المياه وتدفق الهواء أو الماء حسب النظام. في أنظمة التدفئة، راجع تعليمات المصنع والتهوية وأجهزة الحماية، ولا تتجاوز متطلبات فني مختص. سلّم تقريرًا يوضح الأعمال المنفذة والقياسات والقطع المستبدلة وتوصيات الصيانة القادمة.',3),
('النجارة وصناعة الأثاث باستخدام MDF','القياس والرسم التنفيذي','إعداد قائمة قطع دقيقة','ارسم المنتج بأبعاد خارجية واضحة، ثم احسب أبعاد كل قطعة مع مراعاة سماكة اللوح وطريقة التراكب ومكان الحواف. أنشئ قائمة قطع مرقمة تتضمن الطول والعرض والعدد واتجاه الوجه، وراجع مجموع الأبعاد قبل القص. لا تضع مسامير أو براغي قرب الحواف دون مراعاة السماكة ونوع المثبت، واستخدم حماية مناسبة من الغبار.',1),
('النجارة وصناعة الأثاث باستخدام MDF','القص والحواف والتجميع','من القطع إلى التجميع','رقّم القطع فور قصها، وتحقق من تساوي الأزواج وتربيع الزوايا. جهّز الحواف بالطريقة الملائمة، وجرّب المثبتات على قطعة زائدة عند الحاجة. استخدم دليلًا أو قالبًا لتوحيد مواضع الثقوب، وتحقق من القطرية للتأكد من أن الهيكل مربع قبل الشد النهائي. اتبع تعليمات أدوات القص والشفط ووسائل الوقاية من الغبار.',2),
('النجارة وصناعة الأثاث باستخدام MDF','التركيب والتشطيب والجودة','فحص الأثاث قبل التسليم','افحص استقامة الأسطح وثبات الوصلات ومحاذاة الأبواب والأدراج وتساوي الفواصل. تأكد من تغطية الحواف المكشوفة ومعالجة الزوايا وإزالة الرايش وبقايا الغراء. افتح وأغلق الأجزاء المتحركة عدة مرات، ثم راجع ثبات المنتج وسلامة تثبيته وفق تصميمه. سجّل أي انحراف عن المقاسات وخطوة التصنيع التي سبّبته.',3),
('اللحام والأعمال المعدنية','السلامة وتجهيز القطع','تجهيز آمن قبل اللحام','أزل المواد القابلة للاشتعال من منطقة العمل، وتأكد من التهوية ووسائل الوقاية وحالة الكابلات والتأريض ومطفأة الحريق. قس القطع وثبّتها ونظّف منطقة الوصل وحدد ترتيب العمل قبل تشغيل الجهاز. اختبر الإعدادات على عينة مناسبة، ولا تلحم أوعية مغلقة أو مواد مجهولة أو قطعًا ملوثة دون إجراءات معتمدة.',1),
('اللحام والأعمال المعدنية','مبادئ الوصل والتحكم','اختبار عينة الوصلة','يعتمد اختيار العملية والإعدادات على نوع المعدن وسماكته ووضعية اللحام ومتطلبات التصميم. ابدأ بعينة، وافحص انتظام الوصلة وعمق الاندماج الظاهر والتشوهات، ثم عدّل الإعدادات وفق الإجراء المعتمد. تجنب تقديم مظهر الوصلة وحده كدليل على قوتها؛ بعض التطبيقات تتطلب فحوصًا إضافية يقوم بها مختص.',2),
('اللحام والأعمال المعدنية','الفحص والتشطيب وتنظيم الورشة','فحص وتسليم القطعة المعدنية','راجع الأبعاد والاستقامة والتشوهات والحواف الحادة وآثار التناثر. نظف القطعة بالطريقة المناسبة للمادة، واتبع متطلبات الفحص المحددة للمشروع قبل الطلاء أو التسليم. وثّق المادة وطريقة الوصل والإعدادات والملاحظات المهمة، وحافظ على فصل القطع الساخنة ووضع علامات تحذير حتى تبرد بأمان.',3)
) as v(course_title,module_title,lesson_title,body,sort_order)
join public.courses c on c.title=v.course_title
join public.academy_modules m on m.course_id=c.id::text and m.title=v.module_title
where not exists(select 1 from public.academy_lessons l where l.module_id=m.id and l.title=v.lesson_title);

insert into public.academy_admission_questions(course_id,prompt,question_type,options,required,sort_order,active)
select c.id::text,v.prompt,v.question_type,v.options::jsonb,true,v.sort_order,true
from (values
('مبادئ التنجيد وصناعة الكراسي','ما خبرتك السابقة في التنجيد أو تصنيع الأثاث؟','single_choice','["مبتدئ","لدي تجربة بسيطة","لدي خبرة عملية"]',1),
('مبادئ التنجيد وصناعة الكراسي','ما المهارة العملية التي تريد إتقانها بنهاية التكوين؟','text','[]',2),
('مبادئ التنجيد وصناعة الكراسي','هل تستطيع تطبيق تعليمات السلامة واستخدام أدوات الورشة تحت إشراف مناسب؟','yes_no','[]',3),
('الخياطة الصناعية وتصميم المفروشات والستائر','ما خبرتك السابقة في الخياطة أو التعامل مع الأقمشة؟','single_choice','["مبتدئ","أجيد الخياطة الأساسية","لدي خبرة في الخياطة الصناعية"]',1),
('الخياطة الصناعية وتصميم المفروشات والستائر','ما المنتجات التي ترغب في تعلم تنفيذها؟','text','[]',2),
('الخياطة الصناعية وتصميم المفروشات والستائر','هل تستطيع الوصول إلى آلة خياطة للتطبيق العملي أثناء التكوين؟','yes_no','[]',3),
('الكهرباء المعمارية والصناعية','ما خبرتك السابقة في الكهرباء؟','single_choice','["لا توجد خبرة","أساسيات نظرية","خبرة عملية تحت إشراف"]',1),
('الكهرباء المعمارية والصناعية','ما المسار الذي تريد التركيز عليه: تمديدات المباني أم التحكم الصناعي أم كليهما؟','text','[]',2),
('الكهرباء المعمارية والصناعية','هل توافق على الالتزام الصارم بإجراءات العزل والسلامة وعدم تنفيذ أعمال حية دون تأهيل؟','yes_no','[]',3),
('التبريد والتكييف والتدفئة','ما خبرتك السابقة في التبريد أو التكييف أو التدفئة؟','single_choice','["مبتدئ","أعرف المكونات الأساسية","لدي خبرة صيانة عملية"]',1),
('التبريد والتكييف والتدفئة','ما نوع الأنظمة التي تريد التركيز عليها؟','text','[]',2),
('التبريد والتكييف والتدفئة','هل توافق على عدم فتح دوائر وسيط التبريد أو التعامل مع الضغط دون تدريب ومعدات مناسبة؟','yes_no','[]',3),
('النجارة وصناعة الأثاث باستخدام MDF','ما خبرتك في القياس والقص وتجميع الأثاث؟','single_choice','["مبتدئ","لدي خبرة بسيطة","لدي خبرة عملية"]',1),
('النجارة وصناعة الأثاث باستخدام MDF','ما نوع الأثاث الذي ترغب في تعلم تصنيعه؟','text','[]',2),
('النجارة وصناعة الأثاث باستخدام MDF','هل تستطيع استخدام معدات الوقاية والعمل وفق تعليمات السلامة في الورشة؟','yes_no','[]',3),
('اللحام والأعمال المعدنية','ما خبرتك السابقة في اللحام أو الأعمال المعدنية؟','single_choice','["مبتدئ","جربت اللحام سابقًا","لدي خبرة عملية"]',1),
('اللحام والأعمال المعدنية','ما نوع الوصلات أو المنتجات المعدنية التي تريد تعلم تنفيذها؟','text','[]',2),
('اللحام والأعمال المعدنية','هل لديك استعداد للالتزام بمعدات الوقاية والتهوية وقواعد السلامة من الحريق؟','yes_no','[]',3)
) as v(course_title,prompt,question_type,options,sort_order)
join public.courses c on c.title=v.course_title
where not exists(select 1 from public.academy_admission_questions q where q.course_id=c.id::text and q.prompt=v.prompt);
